/* ===== x06_sales.js ===== */
/* ============================================================================
   v5.5 LAYER 6 — Client sales & commercial decisions: lead source/next action,
   public intake form (consent, spam check, duplicates, owner inbox), follow-up
   queue with reminder rules, secure revision-specific approval links,
   questions & counterproposals, scoped client portal, contract generation &
   e-signature (sandbox provider), communication history, repeat/referrals.
   ========================================================================== */
coll('leadsInbox','contracts','comms','clientNotes','clientLinks');
const LEAD_SOURCES=['Referral (client)','Referral (vendor)','Instagram','Google','Walk-in / venue','WedMeGood / portal','Repeat client','Other'];
function leadOf(e){e.lead=e.lead||{source:'',channel:'',ownerId:e.plannerId,nextAction:'',nextDate:null,expectedValuePaise:null,probability:null,referredByClientId:null,referredByVendorId:null};return e.lead}
act('lead-edit',({E,id})=>{const e=id?ev(id):E();const l=leadOf(e);openModal(`${hd('Lead: '+esc(e.name))}<form id="f-ld"><div class="two"><div><label for="lds">Source</label><select id="lds"><option value="">—</option>${LEAD_SOURCES.map(s=>`<option ${l.source===s?'selected':''}>${s}</option>`).join('')}</select></div><div><label for="ldo">Owner</label>${userSel('ldo',l.ownerId,u=>u.active!==false&&u.role!=='staff'&&u.role!=='accountant')}</div></div>${/Referral \(client\)/.test(l.source)||true?`<div class="two"><div><label for="ldrc">Referred by client</label><select id="ldrc"><option value="">—</option>${S.clients.map(c=>`<option value="${c.id}" ${l.referredByClientId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div><label for="ldrv">Referred by vendor</label><select id="ldrv"><option value="">—</option>${S.vendors.filter(v=>v.id!=='v_other').map(v=>`<option value="${v.id}" ${l.referredByVendorId===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div></div>`:''}<div class="two"><div><label for="ldn">Next action</label><input id="ldn" value="${esc(l.nextAction||'')}" placeholder="Call back after they see the venue"></div><div><label for="ldd">By</label><input id="ldd" type="date" value="${l.nextDate||''}"></div></div><div class="two"><div><label for="ldv">Expected value (₹, ex-tax)</label><input id="ldv" inputmode="decimal" value="${l.expectedValuePaise?l.expectedValuePaise/100:''}"></div><div><label for="ldp">Chance of winning %</label><input id="ldp" inputmode="numeric" value="${l.probability??''}"></div></div><div class="help">Expected value × chance feeds the weighted pipeline on Home. Won/lost reasons are asked when the stage changes.</div>${ft('Save')}</form>`);F('f-ld').addEventListener('submit',x=>{x.preventDefault();Object.assign(l,{source:F('lds').value,ownerId:F('ldo').value,referredByClientId:F('ldrc')?F('ldrc').value||null:null,referredByVendorId:F('ldrv')?F('ldrv').value||null:null,nextAction:F('ldn').value.trim(),nextDate:F('ldd').value||null,expectedValuePaise:toPaise(F('ldv').value),probability:F('ldp').value===''?null:Math.min(100,Math.max(0,parseInt(F('ldp').value)||0))});touch(e);audit('update','events',e.id,'lead updated',e.id);save();closeModal();render()})});
/* lead card on pre-confirmation overview */
const _tabOverviewBase=tabOverview;tabOverview=function(e,c){let h=_tabOverviewBase(e,c);if(stageIdx(e.stage)<2&&can('quote')){const l=leadOf(e);const ref=l.referredByClientId?S.clients.find(x=>x.id===l.referredByClientId):null;h+=`<div class="card" style="margin-top:12px"><div class="row between"><div><h3>Lead</h3><div class="small">${l.source?esc(l.source):'<span class="pill warn">source unknown</span>'}${ref?' · referred by '+esc(ref.name):''}${l.referredByVendorId?' · referred by '+esc(vendor(l.referredByVendorId).name):''} · owner ${esc(user(l.ownerId).name)}${l.expectedValuePaise?' · expected '+inr(l.expectedValuePaise)+(l.probability!=null?' × '+l.probability+'%':''):''}</div><div class="small" style="margin-top:4px">${l.nextAction?`Next: <b>${esc(l.nextAction)}</b>${l.nextDate?' by '+fmtDate(l.nextDate)+(l.nextDate<todayStr()?' <span class="pill bad">overdue</span>':''):''}`:'<span class="pill warn">no next action</span>'}</div></div><div class="row" style="gap:6px"><button class="btn sm" data-act="lead-edit">Edit lead</button><button class="btn sm" data-act="comm-log">Log contact</button></div></div>${commsCard(e)}</div>`}return h};
/* stage change asks won/lost reason */
const _mLoseBase=mLose;mLose=function(e){_mLoseBase(e);const f=document.querySelector('.modal form');if(!f)return;f.insertAdjacentHTML('afterbegin',`<label for="lrw">Lost to</label><select id="lrw"><option>Price</option><option>Another planner</option><option>Did it themselves</option><option>Event cancelled</option><option>No response</option><option>Other</option></select>`);const sel=F('lrw');leadOf(e).lostTo=sel.value;sel.addEventListener('change',()=>{leadOf(e).lostTo=sel.value})};
ON_ACCEPT.push(e=>{const l=leadOf(e);l.wonAt=nowISO();if(!l.wonReason)l.wonReason='accepted quote v'+((e.quote.snapshots||[]).length||1)});
/* ---------- Intake form (public) & leads inbox ---------- */
PAGES_EXT.enquire=vEnquire;
function vEnquire(){const co=S.company;const sent=S.ui.enqSent;return `<div class="login"><div class="card" style="max-width:560px;margin:30px auto"><div class="eyebrow">${esc(co.name)}</div><h1 style="font-size:22px">Tell us about your event</h1><div class="small muted">We reply within a working day. ${sb('public web form on your site')}</div>${sent?`<div class="note" style="margin-top:10px">Thank you — we have your enquiry (ref ${esc(sent)}). We will call you.</div>`:`<form id="f-enq" style="margin-top:8px"><label for="eqn">Your name</label><input id="eqn" required><label for="eqp">Phone</label><input id="eqp" required inputmode="tel"><div class="two"><div><label for="eqt">Type of event</label><select id="eqt"><option value="wedding">Wedding</option><option value="corporate">Corporate</option><option value="other">Other</option></select></div><div><label for="eqd">Date (if known)</label><input id="eqd" type="date"></div></div><div class="two"><div><label for="eqg">Guests (approx.)</label><input id="eqg" inputmode="numeric"></div><div><label for="eqb">Budget (₹, optional)</label><input id="eqb" inputmode="decimal"></div></div><label for="eqm">Anything else</label><textarea id="eqm"></textarea><input id="eqw" tabindex="-1" autocomplete="off" style="position:absolute;left:-9999px" aria-hidden="true"><label class="chk"><input type="checkbox" id="eqc" required> I agree that ${esc(co.name)} keeps these details to respond to my enquiry (<a href="#" data-act="privacy-show">how we use them</a>)</label><div class="ft"><button class="btn pri" type="submit">Send enquiry</button></div></form>`}<div class="meta" style="margin-top:10px">Nothing here creates a booking. Enquiries land in the owner's inbox, are checked against existing clients, and become an enquiry in the pipeline only when someone accepts them.</div></div></div>`}
act('privacy-show',({evt})=>{evt.preventDefault();openModal(`${hd('How we use your details')}<p class="small">${esc(S.company.privacy.noticeText)}</p><div class="meta">Notice v${S.company.privacy.noticeVersion} · contact ${esc(S.company.privacy.support)}</div><div class="ft"><button class="btn" data-act="close">Close</button></div>`)});
document.addEventListener('submit',evt=>{if(evt.target.id!=='f-enq')return;evt.preventDefault();if(F('eqw').value){toast('Thank you');S.ui.enqSent='—';saveUI();render();return}const last=+(sessionStorage.getItem('aurivevents.enq.last')||0);if(nowMs()-last<30000)return toast('Please wait a moment before sending again');const phone=F('eqp').value.trim();const name=F('eqn').value.trim();if(normPhone(phone).length!==10)return toast('A 10-digit phone number, please');const dupClient=S.clients.find(c=>normPhone(c.phone)===normPhone(phone));const dupLead=S.leadsInbox.find(l=>normPhone(l.phone)===normPhone(phone)&&l.status==='new');const ref='ENQ-'+Math.random().toString(36).slice(2,7).toUpperCase();S.leadsInbox.push({id:uid(),ref,name,phone,type:F('eqt').value,date:F('eqd').value||null,guests:parseInt(F('eqg').value)||null,budgetPaise:toPaise(F('eqb').value),note:F('eqm').value.trim(),consent:{noticeVersion:S.company.privacy.noticeVersion,at:nowISO()},receivedAt:nowISO(),status:'new',dupClientId:dupClient?dupClient.id:null,dupLeadId:dupLead?dupLead.id:null,source:'Web form'});S.users.filter(u=>u.role==='owner').forEach(o=>S.notes.push({id:uid(),userId:o.id,text:`New web enquiry from ${name} (${F('eqt').value}${F('eqg').value?', '+F('eqg').value+' guests':''})${dupClient?' — matches existing client '+dupClient.name:''}`,ts:nowISO(),read:false,eventId:null}));sessionStorage.setItem('aurivevents.enq.last',String(nowMs()));S.audit.push({ts:nowISO(),userId:null,action:'intake',entity:'leadsInbox',id:ref,detail:name,eventId:null});save();S.ui.enqSent=ref;saveUI();render()});
const _renderGate2=render;render=function(){if(route()==='enquire'||location.hash==='#enquire'){bindUI();document.getElementById('nav').innerHTML='';document.getElementById('tabbar').innerHTML='';document.getElementById('sidefoot').innerHTML='';document.getElementById('app').innerHTML=vEnquire();return}return _renderGate2()};
addPage('leads','Leads & follow-up',vLeads,()=>can('quote'),()=>{const n=S.leadsInbox.filter(l=>l.status==='new').length+followUps().length;return n||''});
function followUps(){const out=[];S.events.filter(e=>stageIdx(e.stage)<2&&e.stage!=='lost'&&!e.archived).forEach(e=>{const l=leadOf(e);if(l.nextDate&&l.nextDate<=todayStr())out.push({kind:'next',e,txt:l.nextAction||'Follow up',due:l.nextDate});if(e.stage==='quoted'&&e.quote.sentAt&&daysUntil(e.quote.sentAt.slice(0,10))<=-3&&!(l.nextDate&&l.nextDate>todayStr()))out.push({kind:'quote',e,txt:'Quote sent '+fmtShort(e.quote.sentAt.slice(0,10))+', no answer',due:e.quote.sentAt.slice(0,10)});if(e.stage==='enquiry'&&!e.quote.lines.length&&daysUntil(e.createdAt.slice(0,10))<=-2)out.push({kind:'noquote',e,txt:'Enquiry '+fmtShort(e.createdAt.slice(0,10))+' without a quote',due:e.createdAt.slice(0,10)})});live(S.clientReqs).filter(r=>r.status==='sent'&&daysUntil(r.sentAt.slice(0,10))<=-2).forEach(r=>{const e=ev(r.eventId);if(e)out.push({kind:'approval',e,txt:r.kind+': '+r.desc+' unanswered',due:r.sentAt.slice(0,10),r})});return out.sort((a,b)=>a.due.localeCompare(b.due))}
function vLeads(){const inbox=S.leadsInbox.slice().reverse();const fu=followUps();const pipe=S.events.filter(e=>stageIdx(e.stage)<2&&e.stage!=='lost'&&!e.archived);const weighted=sum(pipe,e=>{const l=leadOf(e);const v=l.expectedValuePaise||quoteTotals(e).net||0;return Math.round(v*(l.probability==null?50:l.probability)/100)});const won=S.events.filter(e=>stageIdx(e.stage)>=2&&!e.history).length,lost=S.events.filter(e=>e.stage==='lost').length;const bySrc={};S.events.filter(e=>!e.history).forEach(e=>{const s=leadOf(e).source||'unknown';bySrc[s]=bySrc[s]||{n:0,won:0};bySrc[s].n++;if(stageIdx(e.stage)>=2)bySrc[s].won++});
  return `${topbar()}<div class="row between"><h1>Leads & follow-up</h1><div class="row" style="gap:6px"><a class="btn sm" href="#enquire" style="text-decoration:none">Open the public enquiry form</a><button class="btn sm pri" data-act="new-event">+ New enquiry</button></div></div>
  <div class="grid g4" style="margin:12px 0">${stat('Weighted pipeline',inr(weighted),`${pipe.length} open · value × chance (50% where unset)`)}${stat('To follow up',fu.length,fu.filter(x=>daysUntil(x.due)<=-7).length+' older than a week')}${stat('Web enquiries waiting',inbox.filter(l=>l.status==='new').length,'from the public form')}${stat('Won / lost',`${won} / ${lost}`,lost+won?pct(won,won+lost)+' win rate':'')}</div>
  ${inbox.filter(l=>l.status==='new').length?`<div class="card" style="margin-bottom:12px"><h2>Web enquiries</h2><div class="list">${inbox.filter(l=>l.status==='new').map(l=>`<div class="item"><div class="row between"><div><b>${esc(l.name)}</b> · ${esc(l.phone)} · ${l.type}${l.date?' · '+fmtDate(l.date):''}${l.guests?' · '+l.guests+' guests':''}${l.budgetPaise?' · budget '+inr(l.budgetPaise):''}<div class="meta">${esc(l.ref)} · ${fmtTs(l.receivedAt)} · consent v${l.consent.noticeVersion}${l.dupClientId?` · <span class="pill warn">existing client: ${esc((S.clients.find(c=>c.id===l.dupClientId)||{}).name)}</span>`:''}${l.dupLeadId?' · <span class="pill warn">duplicate of an earlier enquiry</span>':''}${l.note?'<br>'+esc(l.note):''}</div></div><div class="row" style="gap:6px"><button class="btn sm" data-act="lead-spam" data-id="${l.id}">Spam / ignore</button><button class="btn sm pri" data-act="lead-accept" data-id="${l.id}">Accept → enquiry</button></div></div></div>`).join('')}</div></div>`:''}
  <div class="card" style="margin-bottom:12px"><h2>Follow-up queue</h2><div class="small muted">Leads with a next action due, quotes unanswered for 3+ days, enquiries without a quote for 2+ days, client decisions unanswered 2+ days. Reminders are prepared, never sent on their own: sending needs a named sender, a recipient who has consented to that channel, and a quiet-hours rule — see Settings → Notifications. ${sb('WhatsApp reminder delivery')}</div><div class="list" style="margin-top:6px">${fu.map(x=>`<div class="item"><div class="row between"><div><span class="pill ${daysUntil(x.due)<=-7?'bad':'warn'}">${({next:'next action',quote:'quote unanswered',noquote:'no quote yet',approval:'client decision'})[x.kind]}</span> <b>${esc(x.e.name)}</b> · ${esc(x.e.client)}<div class="meta">${esc(x.txt)} · owner ${esc(user(leadOf(x.e).ownerId).name)}</div></div><div class="row" style="gap:6px"><button class="btn sm" data-act="lead-remind" data-id="${x.e.id}" data-v="${x.kind}">Prepare reminder</button><button class="btn sm" data-act="lead-edit" data-id="${x.e.id}">Next action</button><button class="btn sm" data-act="open-event" data-id="${x.e.id}">Open</button></div></div></div>`).join('')||'<div class="muted small">Nothing waiting.</div>'}</div></div>
  <div class="card" style="margin-bottom:12px"><h2>Pipeline</h2><div class="scroll"><table><thead><tr><th>Enquiry</th><th>Stage</th><th>Source</th><th class="r">Value</th><th class="r">Chance</th><th>Next action</th><th>Owner</th></tr></thead><tbody>${pipe.map(e=>{const l=leadOf(e);return `<tr><td><a href="#event" data-act="open-event" data-id="${e.id}" style="font-weight:600;text-decoration:none;color:inherit">${esc(e.name)}</a><div class="meta">${esc(e.client)} · ${fmtShort(e.startDate)}</div></td><td>${stagePill(e.stage)}</td><td>${esc(l.source||'—')}</td><td class="r num">${inr(l.expectedValuePaise||quoteTotals(e).net||0)}</td><td class="r num">${l.probability==null?'—':l.probability+'%'}</td><td>${l.nextAction?esc(l.nextAction)+(l.nextDate?' · '+fmtShort(l.nextDate):''):'<span class="pill warn">none</span>'}</td><td>${esc(user(l.ownerId).name)}</td></tr>`}).join('')||'<tr><td colspan="7" class="muted">Empty pipeline.</td></tr>'}</tbody></table></div></div>
  <div class="card"><h3>Where enquiries come from</h3><div class="chips" style="margin-top:6px">${Object.keys(bySrc).map(s=>`<span class="pill grey" style="font-size:12.5px;padding:5px 10px">${esc(s)} · ${bySrc[s].n} · won ${bySrc[s].won}</span>`).join('')}</div><div class="meta" style="margin-top:6px">Counts only; too few to rank sources. Set the source on every enquiry so this means something after a season.</div></div>`}
act('lead-spam',({id})=>{const l=S.leadsInbox.find(x=>x.id===id);l.status='ignored';l.decidedAt=nowISO();save();render()});
act('lead-accept',({id})=>{const l=S.leadsInbox.find(x=>x.id===id);let cl=l.dupClientId?S.clients.find(c=>c.id===l.dupClientId):null;if(!cl){cl=stamp({id:uid(),name:l.name,phone:l.phone,address:'',gstin:'',state:S.company.state||'Kerala',consent:{noticeVersion:l.consent.noticeVersion,whatsapp:true,marketing:false,photos:false,source:'Web enquiry form '+l.ref,updatedAt:nowISO(),updatedBy:UI.userId}});S.clients.push(cl)}const e=stamp({id:uid(),name:`${l.name} ${({wedding:'wedding',corporate:'event',other:'function'})[l.type]}`,client:cl.name,clientId:cl.id,phone:cl.phone,type:l.type,startDate:l.date||addDays(todayStr(),60),endDate:'',venue:'',guests:l.guests||0,contractPaise:0,stage:'enquiry',functions:[],functionDetails:{},pricing:S.company.pricingDefault||'fixed',feePct:S.company.feeDefault||12,gstOn:true,plannerId:UI.userId,quote:{lines:[],sentAt:null,acceptedAt:null},budgetBaseline:{},budget:{},lead:{source:'Web form',channel:'web',ownerId:UI.userId,nextAction:'Call to qualify',nextDate:addDays(todayStr(),1),expectedValuePaise:l.budgetPaise,probability:30,inboxRef:l.ref}});S.events.push(e);l.status='accepted';l.eventId=e.id;l.decidedAt=nowISO();audit('create','events',e.id,'from web enquiry '+l.ref,e.id);save();go('event',e.id)});
act('lead-remind',({id,v})=>{const e=ev(id);const cl=S.clients.find(c=>c.id===e.clientId);const ok=!cl||!cl.consent||cl.consent.whatsapp!==false;const txt=v==='quote'?`Dear ${e.client}, following up on our quote for ${e.name} (${fmtDate(e.startDate)}) sent on ${fmtDate(e.quote.sentAt.slice(0,10))}. Happy to walk you through it or adjust — when suits a call?\n\n— ${me().name}, ${S.company.name}`:`Dear ${e.client}, checking in about ${e.name}. ${leadOf(e).nextAction||''}\n\n— ${me().name}, ${S.company.name}`;if(!ok)return openModal(`${hd('Cannot prepare')}<div class="alert">${esc(e.client)} has not consented to WhatsApp contact (Clients → consent). Call them instead, and log the call.</div><div class="ft"><button class="btn" data-act="close">Close</button></div>`);logComm(e,'whatsapp','out','Reminder: '+(v==='quote'?'quote follow-up':'next action'),true);mCopy('Reminder for '+e.client,txt)});
/* ---------- Communication history ---------- */
function logComm(e,channel,dir,summary,auto){const cid=e.clientId;const recent=S.comms.find(c=>c.eventId===e.id&&c.summary===summary&&nowMs()-new Date(c.ts).getTime()<300000);if(recent)return recent;const c={id:uid(),clientId:cid,eventId:e.id,channel,direction:dir,summary,ts:nowISO(),by:UI.userId,auto:!!auto};S.comms.push(c);return c}
act('comm-log',({E,id})=>{const e=id?ev(id):E();openModal(`${hd('Log a contact: '+esc(e.client))}<form id="f-cm"><div class="two"><div><label for="cmc">Channel</label><select id="cmc"><option>call</option><option>whatsapp</option><option>email</option><option>meeting</option><option>site visit</option></select></div><div><label for="cmd">Direction</label><select id="cmd"><option value="out">We contacted them</option><option value="in">They contacted us</option></select></div></div><label for="cms">What was said / agreed</label><textarea id="cms" required></textarea><label class="chk"><input type="checkbox" id="cmp"> Private staff note (never shown to the client, excluded from client exports)</label>${ft('Log')}</form>`);F('f-cm').addEventListener('submit',x=>{x.preventDefault();if(F('cmp').checked){S.clientNotes.push({id:uid(),clientId:e.clientId,eventId:e.id,text:F('cms').value.trim(),ts:nowISO(),by:UI.userId})}else logComm(e,F('cmc').value,F('cmd').value,F('cms').value.trim(),false);save();closeModal();render()})});
function commsCard(e){const cs=S.comms.filter(c=>c.eventId===e.id).slice().reverse();const ns=S.clientNotes.filter(n=>n.eventId===e.id).slice().reverse();return `<div class="card" style="margin-top:12px"><div class="row between"><h3>Contact history</h3><button class="btn sm" data-act="comm-log">+ Log</button></div><div class="small muted">Calls, messages and meetings with the client, consented channels only. Copied messages are logged automatically.</div><div class="list" style="margin-top:4px">${cs.slice(0,8).map(c=>`<div class="item" style="padding:5px 0" ><span class="pill grey">${c.channel}</span> <span class="small">${c.direction==='out'?'→':'←'} ${esc(c.summary)}</span><div class="meta">${esc(user(c.by).name)} · ${fmtTs(c.ts)}${c.auto?' · auto':''}</div></div>`).join('')||'<div class="muted small">No contact logged.</div>'}</div>${ns.length?`<div class="eyebrow" style="margin-top:8px">Private staff notes</div><div class="list">${ns.map(n=>`<div class="item" style="padding:5px 0"><span class="small">${esc(n.text)}</span><div class="meta">${esc(user(n.by).name)} · ${fmtTs(n.ts)}</div></div>`).join('')}</div>`:''}</div>`}
const _waClientBase=waClient;waClient=function(e){logComm(e,'whatsapp','out','Statement shared',true);return _waClientBase(e)};
/* ---------- Secure revision-specific client links (approvals, questions, counterproposals) ---------- */
function clientLink(r){if(!r.token){r.token=Math.random().toString(36).slice(2,12);r.expiresAt=r.expiresAt||addDays(todayStr(),14);r.decisionMaker=r.decisionMaker||'';r.thread=r.thread||[]}return location.href.split('#')[0]+'#client/'+r.token}
const _mClientReqBase=mClientReq;mClientReq=function(kind,changeId){_mClientReqBase(kind,changeId);const f=document.querySelector('.modal form');if(!f)return;const e=ev(S.ui.eventId);f.querySelector('.ft').insertAdjacentHTML('beforebegin',`<label for="crdm">Named decision-maker</label><input id="crdm" placeholder="Mrs Lakshmi Menon" value="${esc(e.client)}"><div class="two"><div><label for="crex">Link expires</label><input id="crex" type="date" value="${addDays(todayStr(),14)}"></div><div><label for="crrv">Revision shown</label><input id="crrv" value="${kind==='Quote'?'quote v'+((e.quote.snapshots||[]).length||1):kind==='Change order'?'change as priced now':'current'}" readonly></div></div>`);onSubmitBefore(f,()=>{const dm=(F('crdm')||{}).value||e.client,ex=(F('crex')||{}).value||addDays(todayStr(),14);setTimeout(()=>{if(!modalClosed())return;const r=S.clientReqs[S.clientReqs.length-1];if(r&&r.eventId===e.id&&!r.token){r.decisionMaker=dm;r.expiresAt=ex;r.revision=kind==='Quote'?'q'+((e.quote.snapshots||[]).length||1):kind==='Change order'&&changeId?'ch'+changeId+'#'+((S.changes.find(c=>c.id===changeId)||{history:[]}).history.length):'cur';clientLink(r);save();render()}},0)})};
const _waReqBase=waReq;waReq=function(r){const e=ev(r.eventId);clientLink(r);logComm(e,'whatsapp','out',r.kind+' sent for decision: '+r.desc,true);save();return `Dear ${r.decisionMaker||e.client},\n\nPlease decide on *${r.kind}: ${r.desc}* for ${e.name}.\nOpen: ${clientLink(r)}\nThe link works until ${fmtDate(r.expiresAt)} and shows exactly the version we discussed; nothing is changed by viewing it.\n\n— ${me().name}, ${S.company.name}`};
PAGES_EXT.client=vClientLink;PAGES_EXT.portal=()=>vPortal();
function vClientLink(){const tok=S.ui.clientToken||'';const r=S.clientReqs.find(x=>x.token===tok);const back=`<a href="#events" class="btn sm" style="text-decoration:none;margin-top:10px;display:inline-block">← Back to the app</a>`;if(!r)return `<div class="login"><div class="card" style="max-width:560px;margin:30px auto"><h2>This link is not valid</h2><div class="small muted">It may have been revoked, or it points at a decision that was withdrawn.</div>${back}</div></div>`;const e=ev(r.eventId);const expired=r.expiresAt&&r.expiresAt<todayStr();const stale=(()=>{if(r.kind==='Quote')return r.revision!=='q'+((e.quote.snapshots||[]).length||1);if(r.kind==='Change order'&&r.changeId){const ch=S.changes.find(c=>c.id===r.changeId);return !ch||ch.voided||r.revision!=='ch'+ch.id+'#'+(ch.history||[]).length}return false})();const blocked=r.revoked||expired||(stale&&r.status==='sent');const t=taxTermsOf(e);
  let body='';if(r.kind==='Quote'){const snap=(e.quote.snapshots||[]).find(s=>'q'+s.n===r.revision)||(e.quote.snapshots||[]).slice(-1)[0];const q=snap?snap.totals:quoteTotals(e);const lines=snap?snap.lines:quoteTotals(e).lines;body=`<div class="scroll"><table><thead><tr><th>Item</th><th class="r">Qty</th><th class="r">Price</th></tr></thead><tbody>${lines.map(l=>`<tr><td><b>${esc(l.category)}</b> · ${esc(l.desc)}</td><td class="r num">${l.qty}</td><td class="r num">${inr(l.qty*l.unitPricePaise)}</td></tr>`).join('')}<tr><td colspan="2"><b>Subtotal</b></td><td class="r num"><b>${inr(q.net)}</b></td></tr>${q.gst?`<tr><td colspan="2">GST ${t.pct}%</td><td class="r num">${inr(q.gst)}</td></tr><tr><td colspan="2"><b>Total</b></td><td class="r num"><b>${inr(q.gross)}</b></td></tr>`:''}</tbody></table></div>${snap&&(snap.inclusions||snap.exclusions)?`<div class="kv small" style="margin-top:8px"><b>Included</b><span>${esc(snap.inclusions||'—')}</span><b>Not included</b><span>${esc(snap.exclusions||'—')}</span>${snap.allowances?`<b>Allowances</b><span>${esc(snap.allowances)}</span>`:''}${snap.dependencies?`<b>You provide</b><span>${esc(snap.dependencies)}</span>`:''}</div>`:''}`}
  else if(r.kind==='Change order'&&r.changeId){const ch=S.changes.find(c=>c.id===r.changeId);const gst=taxOn(e,ch.clientPaise);body=`<div class="kv"><b>Change</b><span>${esc(ch.desc)}</span><b>Price</b><span>${ch.clientPaise>=0?'+':'−'}${inr(Math.abs(ch.clientPaise))}${t.on?` + GST ${inr(Math.abs(gst))} = <b>${inr(Math.abs(ch.clientPaise+gst))}</b>`:''}</span><b>New contract total</b><span>${inr(grossOf(e,calc(e).contract+(chApproved(ch)?0:ch.clientPaise)))} incl. tax</span></div>`}
  else body=`<div class="kv"><b>${esc(r.kind)}</b><span>${esc(r.desc)}</span></div>${r.docIds?r.docIds.map(id=>{const d=S.docs.find(x=>x.id===id);return d?`<div style="margin-top:6px">${d.type.startsWith('image/')&&docData(d)?`<img src="${docData(d)}" style="max-width:100%;border-radius:8px">`:esc(d.name)}</div>`:''}).join(''):''}`;
  const decided=r.status!=='sent';const thread=(r.thread||[]).map(m=>`<div class="item" style="padding:5px 0"><b>${esc(m.by)}</b> <span class="small muted">${fmtTs(m.ts)}</span><div class="small">${esc(m.text)}${m.proposedPaise!=null?` · proposes <b>${inr(m.proposedPaise)}</b>`:''}</div></div>`).join('');
  return `<div class="login"><div class="card" style="max-width:640px;margin:30px auto"><div class="eyebrow">${esc(S.company.name)}</div><h1 style="font-size:22px">${esc(r.kind)}: ${esc(r.desc)}</h1><div class="small muted">${esc(e.name)} · ${fmtDate(e.startDate)} · for ${esc(r.decisionMaker||e.client)} · ${r.revision?'revision '+esc(r.revision):''}</div>
  ${blocked?`<div class="alert" style="margin-top:10px"><h3>${r.revoked?'This link was withdrawn':expired?'This link expired on '+fmtDate(r.expiresAt):'A newer version exists'}</h3><div class="small">${stale?'The quote or change was revised after this link was sent, so it cannot be approved from here. Ask for the new link.':'Contact '+esc(S.company.name)+' for a fresh link.'}</div></div>`:`<div style="margin-top:10px">${body}</div>${decided?`<div class="note" style="margin-top:10px">${r.status==='approved'?'Approved':'Declined'} by ${esc(r.decidedBy)} on ${fmtTs(r.decidedAt)}${r.note?': '+esc(r.note):''}</div>`:`<form id="f-cl" style="margin-top:10px"><label for="cln2">Your name</label><input id="cln2" required value="${esc(r.decisionMaker||'')}"><label for="clq">Question, condition or counter-proposal (optional)</label><textarea id="clq"></textarea><label for="clp">If you propose a different amount (₹, optional)</label><input id="clp" inputmode="decimal"><div class="ft"><button class="btn danger" type="button" data-act="cl-decline">Decline</button><button class="btn" type="button" data-act="cl-question">Send question / proposal</button><button class="btn pri" type="submit">Approve</button></div></form>`}${thread?`<div class="eyebrow" style="margin-top:10px">Conversation</div><div class="list">${thread}</div>`:''}`}
  <div class="meta" style="margin-top:10px">This page shows only this decision. No internal costs, no other events. Your decision is recorded with your name and time. ${sb('signed public link')} · <a href="#" data-act="privacy-show">how we use your details</a></div>${back}</div></div>`}
BOOT_EXT.push(()=>{const m=location.hash.match(/^#client\/(\w+)/);if(m){S.ui.clientToken=m[1];saveUI()}window.addEventListener('hashchange',()=>{const m2=location.hash.match(/^#client\/(\w+)/);if(m2){S.ui.clientToken=m2[1];saveUI();location.hash='client'}const m3=location.hash.match(/^#portal\/(\w+)/);if(m3){S.ui.portalToken=m3[1];saveUI();location.hash='portal'}});const m3=location.hash.match(/^#portal\/(\w+)/);if(m3){S.ui.portalToken=m3[1];saveUI()}});
const _renderGate3=render;render=function(){const h=location.hash;if(route()==='client'||/^#client\//.test(h)||route()==='portal'||/^#portal\//.test(h)){bindUI();document.getElementById('nav').innerHTML='';document.getElementById('tabbar').innerHTML='';document.getElementById('sidefoot').innerHTML='';document.getElementById('app').innerHTML=/portal/.test(h)?vPortal():vClientLink();return}return _renderGate3()};
function clDecide(status){const r=S.clientReqs.find(x=>x.token===S.ui.clientToken);const name=(F('cln2')||{}).value.trim();const q=(F('clq')||{}).value.trim();const prop=toPaise((F('clp')||{}).value||'');if(!name)return toast('Your name is required');const e=ev(r.eventId);if(status==='question'){if(!q&&prop==null)return toast('Write your question or proposal');r.thread=(r.thread||[]).concat([{by:name,text:q,proposedPaise:prop,ts:nowISO(),side:'client'}]);r.status='sent';[e.plannerId,r.createdBy].filter(Boolean).forEach(u=>S.notes.push({id:uid(),userId:u,text:`${name} ${prop!=null?'proposed '+inr(prop)+' on':'asked about'} ${r.kind}: ${r.desc}${q?' — '+q:''}`,ts:nowISO(),read:false,eventId:e.id}));S.audit.push({ts:nowISO(),userId:null,action:'client_question',entity:'clientReqs',id:r.id,detail:name+': '+q,eventId:e.id});save();render();return toast('Sent')}
  r.status=status;r.decidedAt=nowISO();r.decidedBy=name+' (via link)';r.note=q;r.evidence={ua:navigator.userAgent.slice(0,80),at:nowISO(),revision:r.revision,ip:'sandbox'};if(r.kind==='Change order'&&r.changeId){const ch=S.changes.find(c=>c.id===r.changeId);if(ch)clientDecideChange(ch,status==='approved'?'accepted':'declined',r.decidedBy,q)}S.comms.push({id:uid(),clientId:e.clientId,eventId:e.id,channel:'link',direction:'in',summary:`${r.kind} ${status}: ${r.desc}`,ts:nowISO(),by:null,auto:true});[e.plannerId,r.createdBy].filter(Boolean).forEach(u=>S.notes.push({id:uid(),userId:u,text:`${name} ${status} ${r.kind}: ${r.desc}`,ts:nowISO(),read:false,eventId:e.id}));S.audit.push({ts:nowISO(),userId:null,action:'client_'+status,entity:'clientReqs',id:r.id,detail:name,eventId:e.id});save();render();toast('Recorded, thank you')}
act('cl-decline',()=>clDecide('declined'));act('cl-question',()=>clDecide('question'));document.addEventListener('submit',evt=>{if(evt.target.id==='f-cl'){evt.preventDefault();clDecide('approved')}});
act('req-revoke',({id})=>{const r=S.clientReqs.find(x=>x.id===id);r.revoked=!r.revoked;touch(r);audit('update','clientReqs',r.id,r.revoked?'link revoked':'link re-enabled',r.eventId);save();render()});
act('req-reply',({id})=>{const r=S.clientReqs.find(x=>x.id===id);openModal(`${hd('Reply to the client')}<form id="f-rr2"><div class="list" style="margin-bottom:8px">${(r.thread||[]).map(m=>`<div class="item small" style="padding:4px 0"><b>${esc(m.by)}</b>: ${esc(m.text)}${m.proposedPaise!=null?' · proposes '+inr(m.proposedPaise):''}</div>`).join('')}</div><label for="rrt">Your reply</label><textarea id="rrt" required></textarea><div class="help">If you accept a counter-proposal, revise the quote or change order and send a new link; this thread stays attached to the old one as the record.</div>${ft('Reply')}</form>`);F('f-rr2').addEventListener('submit',x=>{x.preventDefault();r.thread=(r.thread||[]).concat([{by:me().name+' ('+S.company.name+')',text:F('rrt').value.trim(),ts:nowISO(),side:'company'}]);touch(r);save();closeModal();render();mCopy('Reply to '+ev(r.eventId).client,F('rrt')?'':'')})});
/* extend the client approvals tab rows */
const _tabClientApprovalsBase=tabClientApprovals;tabClientApprovals=function(e,c){let h=_tabClientApprovalsBase(e,c);const rs=S.clientReqs.filter(r=>r.eventId===e.id);const extra=rs.map(r=>{const stale=r.kind==='Quote'&&r.revision&&r.revision!=='q'+((e.quote.snapshots||[]).length||1);const th=(r.thread||[]);return `<div class="small" style="margin:4px 0 10px;padding:6px 8px;border:1px dashed var(--line);border-radius:8px"><b>${esc(r.kind)}: ${esc(r.desc)}</b> · link ${r.token?`<span class="mono">…${esc(r.token.slice(-4))}</span> · expires ${fmtShort(r.expiresAt)}${r.revoked?' · <span class="pill bad">revoked</span>':''}${stale?' · <span class="pill warn">superseded by newer revision</span>':''}`:'<span class="pill warn">no link yet (send it)</span>'} · decision-maker ${esc(r.decisionMaker||e.client)}${r.evidence?` · evidence: ${esc(r.decidedBy)} ${fmtTs(r.evidence.at)} rev ${esc(r.evidence.revision||'')}`:''}${th.length?`<div class="list" style="margin-top:4px">${th.map(m=>`<div class="item" style="padding:3px 0"><b>${esc(m.by)}</b>: ${esc(m.text)}${m.proposedPaise!=null?` · <b>proposes ${inr(m.proposedPaise)}</b>`:''} <span class="muted">${fmtTs(m.ts)}</span></div>`).join('')}</div>`:''}<div class="row" style="gap:4px;margin-top:4px">${r.token?`<button class="btn sm" data-act="req-revoke" data-id="${r.id}">${r.revoked?'Re-enable link':'Revoke link'}</button><a class="btn sm" href="#client/${r.token}" style="text-decoration:none">Open as client</a>`:''}${th.length?`<button class="btn sm" data-act="req-reply" data-id="${r.id}">Reply</button>`:''}</div></div>`}).join('');return h+(rs.length?`<div class="card" style="margin-top:12px"><h3>Links, revisions and conversations</h3><div class="small muted">Each link shows one revision; a revised quote or change invalidates older links automatically.</div><div style="margin-top:6px">${extra}</div></div>`:'')+contractCard(e)+portalCard(e)};
/* ---------- Client portal (scoped, token, revocable) ---------- */
function portalFor(e){let p=S.clientLinks.find(x=>x.eventId===e.id&&x.kind==='portal'&&!x.revoked);if(!p){p={id:uid(),kind:'portal',eventId:e.id,clientId:e.clientId,token:Math.random().toString(36).slice(2,12),createdAt:nowISO(),by:UI.userId,revoked:false,opens:[]};S.clientLinks.push(p)}return p}
function portalCard(e){if(!can('client'))return '';const p=S.clientLinks.find(x=>x.eventId===e.id&&x.kind==='portal'&&!x.revoked);return `<div class="card" style="margin-top:12px"><div class="row between"><div><h3>Client portal</h3><div class="small muted">One link for this client and event: approved documents, timeline, decisions, payment schedule, receipts and invoices. Never cost, margin, vendors' prices or other clients.</div></div><div class="row" style="gap:6px">${p?`<a class="btn sm" href="#portal/${p.token}" style="text-decoration:none">Open as client</a><button class="btn sm" data-act="portal-text">Send link</button><button class="btn sm" data-act="portal-revoke">Revoke</button>`:`<button class="btn sm pri" data-act="portal-make">Create link</button>`}</div></div>${p?`<div class="meta" style="margin-top:4px">Created ${fmtTs(p.createdAt)} · opened ${p.opens.length}×${p.opens.length?' · last '+fmtTs(p.opens[p.opens.length-1]):''}</div>`:''}</div>`}
act('portal-make',({E})=>{portalFor(E());save();render()});act('portal-revoke',({E})=>{const p=S.clientLinks.find(x=>x.eventId===E().id&&x.kind==='portal'&&!x.revoked);if(p){p.revoked=true;p.revokedAt=nowISO();audit('update','clientLinks',p.id,'revoked',E().id);save();render()}});
act('portal-text',({E})=>{const e=E();const p=portalFor(e);logComm(e,'whatsapp','out','Portal link shared',true);save();mCopy('Portal link for '+e.client,`Dear ${e.client},\n\nEverything about ${e.name} in one place — approved designs, the schedule, your payments and receipts:\n${location.href.split('#')[0]}#portal/${p.token}\n\nKeep this link private; tell us if it should be switched off.\n\n— ${me().name}, ${S.company.name}`)});
function vPortal(){const tok=S.ui.portalToken||'';const p=S.clientLinks.find(x=>x.token===tok&&x.kind==='portal');const back=`<a href="#events" class="btn sm" style="text-decoration:none;margin-top:10px;display:inline-block">← Back to the app</a>`;if(!p||p.revoked)return `<div class="login"><div class="card" style="max-width:560px;margin:30px auto"><h2>This link is not active</h2>${back}</div></div>`;const e=ev(p.eventId);if(!e)return `<div class="login"><div class="card"><h2>Not found</h2>${back}</div></div>`;if(!p.opens.some(o=>o.slice(0,16)===nowISO().slice(0,16))){p.opens.push(nowISO());save()}const c=calc(e);const ms=live(S.milestones).filter(m=>m.eventId===e.id);const docs=live(S.docs).filter(d=>d.eventId===e.id&&d.audience==='client'||(d.eventId===e.id&&d.kind==='Design'&&!d.superseded&&!d.voided));const reqs=live(S.clientReqs).filter(r=>r.eventId===e.id);const invs=live(S.invoices).filter(i=>i.eventId===e.id);const rcs=live(S.receipts).filter(r=>r.eventId===e.id);const cns=live(S.creditNotes).filter(x=>x.eventId===e.id);const ct=S.contracts.filter(x=>x.eventId===e.id&&x.status==='signed').slice(-1)[0];
  return `<div class="login"><div class="card" style="max-width:720px;margin:30px auto"><div class="eyebrow">${esc(S.company.name)} · client portal</div><h1 style="font-size:24px">${esc(e.name)}</h1><div class="small muted">${esc(e.client)} · ${fmtDate(e.startDate)}${e.endDate?' – '+fmtDate(e.endDate):''} · ${esc(e.venue||'venue to be confirmed')} · ${e.guests} guests · your planner ${esc(user(e.plannerId).name)} ${esc(user(e.plannerId).phone||'')}</div>
  <div class="grid g3" style="margin:12px 0">${stat('Agreed value',inr(c.grossContract),c.grossContract!==c.contract?'incl. GST':'')}${stat('Received with thanks',inr(c.received),'')}${stat(c.clientRefundDue?'Refund due to you':'Balance',inr(c.clientRefundDue||c.toCome),'')}</div>
  <h3>Schedule</h3><div class="list">${fnNames(e).map(f=>{const d=fnOf(e,f);return `<div class="item" style="padding:6px 0"><b>${esc(f)}</b> · ${fmtDate(d.date)}${d.start?' · '+esc(d.start):''}${d.venue?' · '+esc(d.venue):''}${d.guests?' · '+d.guests+' guests':''}</div>`}).join('')}</div>
  <h3 style="margin-top:12px">Payments</h3><div class="scroll"><table><thead><tr><th>Instalment</th><th class="r">Amount</th><th>Due</th><th>Status</th></tr></thead><tbody>${ms.map(m=>{const k=msCalc(m);return `<tr><td>${esc(m.desc)}</td><td class="r num">${inr(m.amountPaise)}</td><td>${fmtDate(m.dueDate)}</td><td>${k.left<=0?'<span class="pill ok">received</span>':k.overdue?'<span class="pill bad">overdue</span>':'<span class="pill warn">due</span>'}${(S.payLinks||[]).some(l=>l.milestoneId===m.id&&l.status==='created')?' <a href="#pay/'+(S.payLinks.find(l=>l.milestoneId===m.id&&l.status==='created').token)+'">pay online</a>':''}</td></tr>`}).join('')}</tbody></table></div>
  ${rcs.length||invs.length||cns.length?`<h3 style="margin-top:12px">Receipts, invoices, credit notes</h3><div class="list">${invs.map(i=>`<div class="item" style="padding:5px 0"><b>Invoice ${esc(i.no)}</b> · ${fmtDate(i.date)} · ${inr(i.amountPaise)}${i.reversedBy?' · reversed':''}</div>`).join('')}${cns.map(x=>`<div class="item" style="padding:5px 0"><b>Credit note ${esc(x.no)}</b> · ${fmtDate(x.date)} · ${inr(x.amountPaise)}</div>`).join('')}${rcs.map(r=>`<div class="item" style="padding:5px 0">Receipt · ${fmtDate(r.date)} · ${inr(r.amountPaise)} · ${esc(r.mode)}${r.ref?' · '+esc(r.ref):''}</div>`).join('')}</div>`:''}
  <h3 style="margin-top:12px">Your decisions</h3><div class="list">${reqs.map(r=>`<div class="item" style="padding:5px 0"><b>${esc(r.kind)}</b>: ${esc(r.desc)} · <span class="pill ${r.status==='approved'?'ok':r.status==='declined'?'bad':'warn'}">${r.status==='sent'?'awaiting you':r.status}</span>${r.status==='sent'&&r.token&&!r.revoked?` · <a href="#client/${r.token}">decide</a>`:''}${r.decidedAt?' · '+fmtTs(r.decidedAt):''}</div>`).join('')||'<div class="muted small">Nothing pending.</div>'}</div>
  ${ct?`<h3 style="margin-top:12px">Agreement</h3><div class="item" style="padding:5px 0">Contract v${ct.version} signed by ${esc(ct.signer.name)} on ${fmtTs(ct.signer.ts)} · <a href="#" data-act="contract-view" data-id="${ct.id}">read</a></div>`:''}
  ${docs.length?`<h3 style="margin-top:12px">Shared documents</h3><div class="list">${docs.map(d=>`<div class="item" style="padding:5px 0">${esc(d.name)} ${d.version>1?'v'+d.version:''}${docData(d)?` · <a href="#" data-act="view-doc" data-id="${d.id}">open</a>`:''}</div>`).join('')}</div>`:''}
  <div class="meta" style="margin-top:12px">Questions: ${esc(user(e.plannerId).name)} · ${esc(S.company.privacy.support)} · <a href="#" data-act="privacy-show">how we use your details</a> ${sb('authenticated portal')}</div>${back}</div></div>`}
/* ---------- Contracts & e-signature (sandbox provider) ---------- */
const DEFAULT_CONTRACT=`SERVICE AGREEMENT\n\nBetween {{company}} ("the Planner") and {{client}} ("the Client") for {{event}} on {{date}} at {{venue}}.\n\n1. Scope: as per quote {{quoteRef}} dated {{quoteDate}}: {{inclusions}}\n2. Not included: {{exclusions}}\n3. Price: {{net}} plus GST where applicable; total {{gross}}. Payment: {{terms}}.\n4. Changes: any change to scope is priced in writing and takes effect only when accepted by the Client and the Planner.\n5. Cancellation by the Client: advances are applied against costs already committed to vendors; the Planner's cancellation charge is {{cancelPolicy}}.\n6. Client responsibilities: {{dependencies}}\n7. Liability is limited to the fees paid under this agreement. Force majeure applies to both parties.\n\nThis template was drafted by us and has NOT been reviewed by a lawyer — unknown whether it is enforceable as written. Replace it in Settings → Company → Contract template before real use.`;
function contractText(e,snap){const tpl=S.company.contractTemplate||DEFAULT_CONTRACT;const q=snap?snap.totals:quoteTotals(e);const m={company:S.company.name,client:e.client,event:e.name,date:fmtDate(e.startDate),venue:e.venue||'venue to be confirmed',quoteRef:'v'+(snap?snap.n:(e.quote.snapshots||[]).length||1),quoteDate:fmtDate((snap?snap.ts:e.quote.sentAt||nowISO()).slice(0,10)),inclusions:(snap?snap.inclusions:e.quote.inclusions)||'as per quote lines',exclusions:(snap?snap.exclusions:e.quote.exclusions)||'none stated',net:inr(q.net),gross:inr(q.gross),terms:(snap?snap.terms:e.quote.terms)||(S.company.planDefault||[40,40,20]).join('/')+'% instalments',cancelPolicy:S.company.cancelPolicy||'unknown — set in Settings',dependencies:(snap?snap.dependencies:e.quote.dependencies)||'none stated'};return tpl.replace(/\{\{(\w+)\}\}/g,(_,k)=>m[k]??'')}
function contractCard(e){if(!can('client'))return '';const cs=S.contracts.filter(x=>x.eventId===e.id).slice().reverse();return `<div class="card" style="margin-top:12px"><div class="row between"><div><h3>Contract</h3><div class="small muted">Generated from the template and the accepted quote version; signed on the client link with a one-time code and a recorded signature event. ${sb('e-signature provider (Leegality / DocuSign)')}</div></div>${stageIdx(e.stage)>=1&&!locked(e)?`<button class="btn sm pri" data-act="contract-make">Generate v${cs.length+1}</button>`:''}</div><div class="list" style="margin-top:6px">${cs.map(x=>`<div class="item" style="padding:6px 0"><div class="row between"><div><b>Contract v${x.version}</b> · from quote v${x.snapshotN} · <span class="pill ${x.status==='signed'?'ok':x.status==='sent'?'warn':x.status==='void'?'bad':'grey'}">${x.status}</span>${x.signer?` · signed by ${esc(x.signer.name)} ${fmtTs(x.signer.ts)} (code ${esc(x.signer.otp)}, ${esc(x.signer.ua)})`:''}</div><div class="row" style="gap:4px"><button class="btn sm" data-act="contract-view" data-id="${x.id}">Read</button>${x.status==='draft'?`<button class="btn sm pri" data-act="contract-send" data-id="${x.id}">Send for signature</button>`:''}${x.status==='sent'?`<a class="btn sm" href="#client/${x.token}" style="text-decoration:none">Open as client</a>`:''}${x.status!=='void'&&x.status!=='signed'?`<button class="btn sm" data-act="contract-void" data-id="${x.id}">Void</button>`:''}${x.status==='signed'?`<button class="btn sm" data-act="contract-pdf" data-id="${x.id}">PDF</button>`:''}</div></div></div>`).join('')||'<div class="muted small">No contract generated.</div>'}</div></div>`}
act('contract-make',({E})=>{const e=E();const snap=(e.quote.snapshots||[]).slice(-1)[0];const c=stamp({id:'ct_'+uid(),eventId:e.id,version:S.contracts.filter(x=>x.eventId===e.id).length+1,snapshotN:snap?snap.n:1,text:contractText(e,snap),status:'draft',signer:null,token:null});S.contracts.push(c);audit('create','contracts',c.id,'v'+c.version,e.id);save();render()});
act('contract-view',({id,evt})=>{if(evt)evt.preventDefault();const c=S.contracts.find(x=>x.id===id);openModal(`${hd('Contract v'+c.version)}<pre class="small" style="white-space:pre-wrap">${esc(c.text)}</pre>${c.signer?`<div class="note">Signed by ${esc(c.signer.name)} · ${fmtTs(c.signer.ts)} · OTP ${esc(c.signer.otp)} · ${esc(c.signer.ua)}</div>`:''}<div class="ft"><button class="btn" data-act="close">Close</button></div>`)});
act('contract-send',({id})=>{const c=S.contracts.find(x=>x.id===id);const e=ev(c.eventId);const r=stamp({id:uid(),eventId:e.id,kind:'Contract',desc:'Service agreement v'+c.version,contractId:c.id,sentAt:nowISO(),status:'sent',decidedAt:null,decidedBy:'',note:'',decisionMaker:e.client,expiresAt:addDays(todayStr(),14),revision:'ct'+c.version,thread:[]});clientLink(r);S.clientReqs.push(r);c.status='sent';c.token=r.token;c.sentAt=nowISO();touch(c);audit('update','contracts',c.id,'sent',e.id);logComm(e,'whatsapp','out','Contract v'+c.version+' sent for signature',true);save();render();mCopy('Contract for '+e.client,`Dear ${e.client},\n\nPlease read and sign our agreement for ${e.name}:\n${clientLink(r)}\nYou will be asked for a one-time code sent to your phone.\n\n— ${me().name}, ${S.company.name}`)});
act('contract-void',({id})=>{const c=S.contracts.find(x=>x.id===id);c.status='void';touch(c);const r=S.clientReqs.find(x=>x.contractId===c.id);if(r)r.revoked=true;save();render()});
/* contract signing on the client link: override body for kind Contract */
const _vClientLinkBase=vClientLink;vClientLink=function(){const r=S.clientReqs.find(x=>x.token===(S.ui.clientToken||''));if(!r||r.kind!=='Contract')return _vClientLinkBase();const c=S.contracts.find(x=>x.id===r.contractId);const e=ev(r.eventId);const back=`<a href="#events" class="btn sm" style="text-decoration:none;margin-top:10px;display:inline-block">← Back to the app</a>`;if(r.revoked||c.status==='void')return `<div class="login"><div class="card" style="max-width:560px;margin:30px auto"><h2>This agreement was withdrawn</h2>${back}</div></div>`;const otp=S.ui.signOtp;return `<div class="login"><div class="card" style="max-width:720px;margin:30px auto"><div class="eyebrow">${esc(S.company.name)} · agreement</div><h1 style="font-size:22px">Service agreement v${c.version}</h1><div class="small muted">${esc(e.name)} · for ${esc(r.decisionMaker||e.client)}</div><pre class="small" style="white-space:pre-wrap;max-height:50vh;overflow:auto;border:1px solid var(--line);border-radius:8px;padding:10px;margin-top:8px">${esc(c.text)}</pre>${c.status==='signed'?`<div class="note">Signed by ${esc(c.signer.name)} on ${fmtTs(c.signer.ts)}.</div>`:`<form id="f-sign"><label for="sgn">Full name of the signatory</label><input id="sgn" required value="${esc(r.decisionMaker||e.client)}"><label for="sgp">Phone for the one-time code</label><input id="sgp" inputmode="tel" value="${esc(e.phone||'')}">${otp?`<div class="note">Code sent ${sb('SMS OTP')}: <b class="num">${otp}</b></div><label for="sgo">Enter the code</label><input id="sgo" class="big" inputmode="numeric" maxlength="6">`:''}<label class="chk"><input type="checkbox" id="sga" required> I have read the agreement and sign it on behalf of ${esc(e.client)}</label><div class="ft">${otp?'<button class="btn pri" type="submit">Sign</button>':'<button class="btn pri" type="button" data-act="sign-otp">Send me a code</button>'}</div></form>`}<div class="meta" style="margin-top:10px">Signature evidence: name, phone, code, time, device. ${sb('e-signature provider audit trail')}</div>${back}</div></div>`};
act('sign-otp',()=>{S.ui.signOtp=sandboxCode();saveUI();render()});
document.addEventListener('submit',evt=>{if(evt.target.id!=='f-sign')return;evt.preventDefault();const r=S.clientReqs.find(x=>x.token===(S.ui.clientToken||''));const c=S.contracts.find(x=>x.id===r.contractId);if(F('sgo').value.trim()!==S.ui.signOtp)return toast('Wrong code');const e=ev(r.eventId);c.status='signed';c.signer={name:F('sgn').value.trim(),phone:F('sgp').value.trim(),otp:S.ui.signOtp,ts:nowISO(),ua:deviceName(),ip:'sandbox'};c.signedTextHash=String(c.text.length)+'-'+c.text.split('').reduce((a,ch)=>(a*31+ch.charCodeAt(0))>>>0,7);r.status='approved';r.decidedAt=nowISO();r.decidedBy=c.signer.name+' (e-signed)';r.evidence={ua:c.signer.ua,at:c.signer.ts,revision:r.revision};const d=stamp({id:uid(),eventId:e.id,name:'Signed agreement v'+c.version+'.txt',type:'text/plain',size:c.text.length,data:'',stored:'idb',audience:'confidential',kind:'Contract',folder:'Contracts',tags:['signed'],version:c.version,contractId:c.id});putFile(d.id,'data:text/plain;base64,'+btoa(unescape(encodeURIComponent(c.text+'\n\nSIGNED: '+c.signer.name+' '+c.signer.ts))));S.docs.push(d);[e.plannerId].forEach(u=>S.notes.push({id:uid(),userId:u,text:`${c.signer.name} signed the agreement v${c.version} for ${e.name}`,ts:nowISO(),read:false,eventId:e.id}));S.audit.push({ts:nowISO(),userId:null,action:'client_signed',entity:'contracts',id:c.id,detail:c.signer.name,eventId:e.id});S.ui.signOtp=null;save();render();toast('Signed. Thank you.')});
act('contract-pdf',({id})=>{const c=S.contracts.find(x=>x.id===id);const e=ev(c.eventId);downloadBlob('agreement-'+e.name.replace(/\W+/g,'_')+'-v'+c.version+'.pdf',makePdf('Service agreement v'+c.version,c.text.split('\n').concat(['','SIGNED: '+c.signer.name+' · '+fmtTs(c.signer.ts)+' · code '+c.signer.otp])))});
